// Excel to CSV conversion utility - #{#xls1b}
// Converts XLS/XLSX files to CSV text for consumption by existing bank parsers

import * as XLSX from 'xlsx';

/**
 * Convert an Excel file (XLS or XLSX) to CSV text.
 * Reads the first sheet and outputs comma-separated values.
 *
 * @param buffer - The Excel file content as an ArrayBuffer
 * @returns CSV text string
 * @throws Error if the file is invalid or contains no sheets
 */
export function convertExcelToCSV(buffer: ArrayBuffer): string {
	const workbook = XLSX.read(buffer, { type: 'array', cellDates: true, dateNF: 'yyyy-mm-dd' });
	const firstSheetName = workbook.SheetNames[0];
	if (!firstSheetName) {
		throw new Error('Excel file contains no sheets');
	}
	const sheet = workbook.Sheets[firstSheetName];
	return XLSX.utils.sheet_to_csv(sheet);
}

/**
 * Detect whether a File is an Excel file based on extension or MIME type.
 *
 * @param file - The File object to check
 * @returns true if the file is XLS or XLSX
 */
export function isExcelFile(file: File): boolean {
	const extension = file.name.toLowerCase().split('.').pop();
	if (extension === 'xls' || extension === 'xlsx') return true;
	if (
		file.type === 'application/vnd.ms-excel' ||
		file.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
	)
		return true;
	return false;
}

